    {'name':'Paul Miller','email':'paul_mill@gmail.com','amount':10.0,'description':'Thermometer'}
]

results=[]
for t in venmo_targets:
    try:
        resp=apis.venmo.create_transaction(receiver_email=t['email'], amount=t['amount'], access_token=venmo_token, description=t['description'], private=True)
        results.append({'name':t['name'],'email':t['email'],'amount':t['amount'],'description':t['description'],'private':True,'status':'ok','resp':resp,'transaction_id':resp.get('transaction_id')})
    except Exception as e:
        results.append({'name':t['name'],'email':t['email'],'amount':t['amount'],'description':t['description'],'private':True,'status':'fail','error':str(e)})

